package com.voicetxt.reader;
import android.app.*;import android.content.Intent;import android.os.Bundle;import android.view.*;import java.util.concurrent.atomic.*;import java.util.function.BooleanSupplier;
public class PreviewPauseTest extends Instrumentation {
    AtomicReference<Throwable> failure=new AtomicReference<>();
    void ui(Runnable action){runOnMainSync(()->{try{action.run();}catch(Throwable e){failure.set(e);}});if(failure.get()!=null)throw new AssertionError(failure.get());}
    void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
    void await(BooleanSupplier predicate,String label)throws Exception{long end=android.os.SystemClock.elapsedRealtime()+30000;while(android.os.SystemClock.elapsedRealtime()<end){AtomicBoolean yes=new AtomicBoolean();ui(()->yes.set(predicate.getAsBoolean()));if(yes.get())return;Thread.sleep(50);}throw new AssertionError("timed out: "+label);}
    View find(View v,String desc){if(desc.equals(String.valueOf(v.getContentDescription())))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View match=find(((ViewGroup)v).getChildAt(i),desc);if(match!=null)return match;}return null;}
    void click(MainActivity a,String desc){View v=find(a.voicePicker.panel,desc);check(v!=null,"button missing: "+desc);v.performClick();}
    @Override public void onCreate(Bundle b){super.onCreate(b);start();}
    @Override public void onStart(){Bundle result=new Bundle();MainActivity activity=null;boolean passed=false;try{
        Intent intent=new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);activity=(MainActivity)startActivitySync(intent);final MainActivity a=activity;
        await(()->a.offlineReady&&a.system.initialized,"voice engines ready");ui(()->a.chooseVoice());final String[] selected={null};ui(()->{selected[0]=a.voicePicker.host.selectedKey();a.voicePicker.tab=0;a.voicePicker.refresh();click(a,"试听 流畅女声");check(find(a.voicePicker.panel,"暂停试听 流畅女声")!=null,"offline pause state missing");});
        await(()->a.latestStatus.startsWith("正在试听："),"offline sample started");ui(()->{click(a,"暂停试听 流畅女声");check(a.previewKey.isEmpty()&&a.voicePicker.previewKey.isEmpty(),"offline sample not cancelled");check(find(a.voicePicker.panel,"试听 流畅女声")!=null,"offline play state not restored");});Thread.sleep(300);ui(()->check(a.previewKey.isEmpty(),"stale callback resurrected preview"));result.putBoolean("offlinePause",true);
        final String[] systemName={null};ui(()->{a.voicePicker.tab=1;a.voicePicker.refresh();for(VoicePicker.Item item:a.voicePicker.host.items())if(item.tab==1&&item.title.startsWith("荣耀")){systemName[0]=item.title;break;}check(systemName[0]!=null,"offline system voice missing");click(a,"试听 "+systemName[0]);check(find(a.voicePicker.panel,"暂停试听 "+systemName[0])!=null,"system pause state missing");});await(()->a.latestStatus.startsWith("正在试听："),"system sample started");ui(()->{click(a,"暂停试听 "+systemName[0]);check(a.previewKey.isEmpty()&&a.voicePicker.previewKey.isEmpty(),"system sample not cancelled");check(find(a.voicePicker.panel,"试听 "+systemName[0])!=null,"system play state not restored");});result.putBoolean("systemPause",true);
        ui(()->{a.voicePicker.tab=0;a.voicePicker.refresh();click(a,"试听 流畅女声");});await(()->a.previewKey.isEmpty(),"natural preview completion");ui(()->{check(find(a.voicePicker.panel,"试听 流畅女声")!=null,"completion did not restore play button");check(selected[0].equals(a.voicePicker.host.selectedKey()),"preview changed selected voice");});result.putBoolean("naturalCompletionReset",true);result.putString("result","PASS: actual offline/system preview play-pause; no stale reset; natural completion resets icon; selected voice unchanged");passed=true;
    }catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));}finally{if(activity!=null){final MainActivity a=activity;ui(()->{if(a.voicePicker!=null)a.voicePicker.dismiss();a.finish();});}}finish(passed?-1:0,result);}
}
